CREATE TABLE IF NOT EXISTS `clan_members` (
  `id` INT NOT NULL,
  `username` VARCHAR(45) NOT NULL DEFAULT '',
  `clan` VARCHAR(45) NOT NULL DEFAULT '',
  `clan_name` VARCHAR(45) NOT NULL DEFAULT '',
  `clan_id` INT NOT NULL DEFAULT 0,
  `owner` TINYINT NOT NULL DEFAULT 0,
  `exp` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`), KEY `idx_clan` (`clan`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `friends` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `uid` INT NOT NULL DEFAULT 0, `username` VARCHAR(45) NOT NULL DEFAULT '',
  `fid` INT NOT NULL DEFAULT 0, `fname` VARCHAR(45) NOT NULL DEFAULT '',
  `bid` INT NOT NULL DEFAULT 0, `bname` VARCHAR(45) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`), KEY `idx_uid` (`uid`), KEY `idx_fid` (`fid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `sidepokemon` (
  `id` INT NOT NULL AUTO_INCREMENT, `owner` INT NOT NULL DEFAULT 0,
  `name` VARCHAR(80) NOT NULL DEFAULT '', `a1` VARCHAR(80) NULL, `a2` VARCHAR(80) NULL,
  `a3` VARCHAR(80) NULL, `a4` VARCHAR(80) NULL, `lvl` INT NOT NULL DEFAULT 1,
  `exp` BIGINT NOT NULL DEFAULT 0, `t1` VARCHAR(30) NULL, `t2` VARCHAR(30) NULL,
  `rowner` VARCHAR(45) NULL, PRIMARY KEY (`id`), KEY `idx_owner` (`owner`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `utraded` (
  `id` INT NOT NULL AUTO_INCREMENT, `tradeid` INT NOT NULL DEFAULT 0, `oid` INT NOT NULL DEFAULT 0,
  `owner` INT NOT NULL DEFAULT 0, `name` VARCHAR(80) NOT NULL DEFAULT '',
  `a1` VARCHAR(80) NULL, `a2` VARCHAR(80) NULL, `a3` VARCHAR(80) NULL, `a4` VARCHAR(80) NULL,
  `lvl` INT NOT NULL DEFAULT 1, `exp` BIGINT NOT NULL DEFAULT 0, `rowner` VARCHAR(45) NULL,
  `time` BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

ALTER TABLE `upfortrade`
  ADD COLUMN IF NOT EXISTS `pid` INT NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `name` VARCHAR(80) NOT NULL DEFAULT '',
  ADD COLUMN IF NOT EXISTS `a1` VARCHAR(80) NULL,
  ADD COLUMN IF NOT EXISTS `a2` VARCHAR(80) NULL,
  ADD COLUMN IF NOT EXISTS `a3` VARCHAR(80) NULL,
  ADD COLUMN IF NOT EXISTS `a4` VARCHAR(80) NULL,
  ADD COLUMN IF NOT EXISTS `lvl` INT NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS `exp` BIGINT NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS `rowner` VARCHAR(45) NULL,
  ADD COLUMN IF NOT EXISTS `date` BIGINT NOT NULL DEFAULT 0;


ALTER TABLE `upfortrade` ENGINE=InnoDB;

CREATE TABLE IF NOT EXISTS `trade_offers` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `listing_id` INT NOT NULL,
  `listing_pokemon_id` INT NOT NULL,
  `listing_owner_id` INT NOT NULL,
  `offerer_id` INT NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'pending',
  `created_at` BIGINT NOT NULL DEFAULT 0,
  `resolved_at` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_trade_offer_listing` (`listing_id`,`status`),
  KEY `idx_trade_offer_owner` (`listing_owner_id`,`status`),
  KEY `idx_trade_offer_offerer` (`offerer_id`,`status`),
  KEY `idx_trade_offer_listing_pokemon` (`listing_pokemon_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `trade_offer_items` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `offer_id` BIGINT UNSIGNED NOT NULL,
  `pokemon_id` INT NOT NULL,
  `original_owner_id` INT NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_trade_offer_items_pokemon` (`pokemon_id`),
  KEY `idx_trade_offer_items_offer` (`offer_id`),
  KEY `idx_trade_offer_items_owner` (`original_owner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `live_battle_members` (
  `userid` INT NOT NULL, `username` VARCHAR(45) NOT NULL DEFAULT '',
  `your_id` INT NOT NULL DEFAULT 0, `your_username` VARCHAR(45) NOT NULL DEFAULT '',
  `time` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`userid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `live_battle_offer` (
  `offer_id` INT NOT NULL AUTO_INCREMENT, `userid` INT NOT NULL DEFAULT 0, `username` VARCHAR(45) NOT NULL DEFAULT '',
  `your_id` INT NOT NULL DEFAULT 0, `your_username` VARCHAR(45) NOT NULL DEFAULT '', `offer` TEXT NULL,
  `time` BIGINT NOT NULL DEFAULT 0, PRIMARY KEY (`offer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `live_battle` (
  `id` INT NOT NULL AUTO_INCREMENT, `uid_1` INT NOT NULL DEFAULT 0, `uid_2` INT NOT NULL DEFAULT 0,
  `created_at` BIGINT NOT NULL DEFAULT 0,
  `choose_1` TINYINT NOT NULL DEFAULT 0, `choose_2` TINYINT NOT NULL DEFAULT 0,
  `initialized_1` TINYINT NOT NULL DEFAULT 0, `initialized_2` TINYINT NOT NULL DEFAULT 0,
  `pokemon_choice_1` INT NOT NULL DEFAULT 0, `pokemon_choice_2` INT NOT NULL DEFAULT 0,
  `pokemon_attack_1` VARCHAR(90) NOT NULL DEFAULT '', `pokemon_attack_1_2` VARCHAR(90) NOT NULL DEFAULT '',
  `pokemon_attack_2` VARCHAR(90) NOT NULL DEFAULT '', `pokemon_attack_2_2` VARCHAR(90) NOT NULL DEFAULT '',
  `user_position_1` INT NOT NULL DEFAULT 0, `user_position_2` INT NOT NULL DEFAULT 0,
  `user_position_1_2` INT NOT NULL DEFAULT 0, `user_position_2_2` INT NOT NULL DEFAULT 0,
  `user_time_1` BIGINT NOT NULL DEFAULT 0, `user_time_2` BIGINT NOT NULL DEFAULT 0,
  `user_time_1_2` BIGINT NOT NULL DEFAULT 0, `user_time_2_2` BIGINT NOT NULL DEFAULT 0,
  `_2` TEXT NULL, PRIMARY KEY (`id`), KEY `idx_live_pair` (`uid_1`,`uid_2`), KEY `idx_live_created` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `live_battle_challenges` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  `challenger_id` INT NOT NULL, `target_id` INT NOT NULL, `battle_id` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `status` ENUM('pending','accepted','declined','cancelled','expired') NOT NULL DEFAULT 'pending',
  `created_at` BIGINT NOT NULL DEFAULT 0, `responded_at` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_live_challenge_target` (`target_id`,`status`,`created_at`),
  KEY `idx_live_challenge_challenger` (`challenger_id`,`status`,`created_at`),
  KEY `idx_live_challenge_battle` (`battle_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `bot_trainers` (
  `user_id` INT NOT NULL,
  `bot_index` INT NOT NULL,
  `enabled` TINYINT NOT NULL DEFAULT 1,
  `trainer_sprite` TINYINT NOT NULL DEFAULT 1,
  `world_key` VARCHAR(24) NOT NULL DEFAULT 'vortex',
  `map_key` VARCHAR(64) NOT NULL DEFAULT '1',
  `x` INT NOT NULL DEFAULT 1,
  `y` INT NOT NULL DEFAULT 1,
  `next_action_at` BIGINT NOT NULL DEFAULT 0,
  `last_action_at` BIGINT NOT NULL DEFAULT 0,
  `last_action` VARCHAR(32) NOT NULL DEFAULT '',
  `last_wild_name` VARCHAR(80) NOT NULL DEFAULT '',
  `last_wild_level` INT NOT NULL DEFAULT 0,
  `wild_battles` INT UNSIGNED NOT NULL DEFAULT 0,
  `wild_wins` INT UNSIGNED NOT NULL DEFAULT 0,
  `captures` INT UNSIGNED NOT NULL DEFAULT 0,
  `player_battles` INT UNSIGNED NOT NULL DEFAULT 0,
  `player_wins` INT UNSIGNED NOT NULL DEFAULT 0,
  `player_losses` INT UNSIGNED NOT NULL DEFAULT 0,
  `created_at` BIGINT NOT NULL DEFAULT 0,
  `updated_at` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uq_bot_trainers_index` (`bot_index`),
  KEY `idx_bot_trainers_due` (`enabled`,`next_action_at`),
  KEY `idx_bot_trainers_location` (`enabled`,`world_key`,`map_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `promo_codes` (
  `id` INT NOT NULL AUTO_INCREMENT, `code` VARCHAR(90) NOT NULL, `owner` VARCHAR(45) NULL,
  `type` VARCHAR(30) NOT NULL DEFAULT 'money', `prize` VARCHAR(90) NULL, `quantity` INT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`), UNIQUE KEY `uq_code` (`code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `unotify` (
  `id` INT NOT NULL AUTO_INCREMENT, `owner` INT NOT NULL DEFAULT 0, `pid` INT NOT NULL DEFAULT 0,
  `powner` INT NOT NULL DEFAULT 0, `prowner` VARCHAR(45) NULL, `ra` INT NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`), KEY `idx_owner` (`owner`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `lotto` (
  `uid` INT NOT NULL, `tickets` INT NOT NULL DEFAULT 0, `money` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`uid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `beta_test` (`id` INT NOT NULL AUTO_INCREMENT, `username` VARCHAR(45), `code` VARCHAR(80), PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `beta_emails` (`id` INT NOT NULL AUTO_INCREMENT, `email` VARCHAR(190), PRIMARY KEY (`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

