-- Production account compatibility -------------------------------------------------
ALTER TABLE `members`
  MODIFY COLUMN `password` VARCHAR(255) NULL,
  MODIFY COLUMN `email` VARCHAR(190) NULL,
  MODIFY COLUMN `ip` VARCHAR(64) NULL,
  MODIFY COLUMN `secret_key` VARCHAR(64) NULL;

CREATE TABLE IF NOT EXISTS `password_resets` (
  `user_id` INT NOT NULL,
  `token_hash` CHAR(64) NOT NULL,
  `expires_at` BIGINT NOT NULL DEFAULT 0,
  `created_at` BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `uq_password_resets_token` (`token_hash`),
  KEY `idx_password_resets_expiry` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ALTER TABLE `members` ADD UNIQUE KEY `uq_members_username` (`username`);
ALTER TABLE `members` ADD UNIQUE KEY `uq_members_email` (`email`);
ALTER TABLE `members` ADD KEY `idx_members_points` (`points`), ADD KEY `idx_members_totalexp` (`totalexp`);
ALTER TABLE `pokemon` ADD KEY `idx_pokemon_owner` (`owner`), ADD KEY `idx_pokemon_name` (`name`);
ALTER TABLE `pguide` ADD KEY `idx_pguide_name` (`name`), ADD KEY `idx_pguide_starter` (`starter`);
ALTER TABLE `online` ADD UNIQUE KEY `uq_online_id` (`id`), ADD KEY `idx_online_time` (`time`(20));
ALTER TABLE `mapusers` ADD UNIQUE KEY `uq_mapusers_id` (`id`), ADD KEY `idx_mapusers_map` (`map`);
ALTER TABLE `messages`
  MODIFY COLUMN `subject` VARCHAR(190) NULL,
  MODIFY COLUMN `message` TEXT NULL,
  ADD KEY `idx_messages_receiver` (`receiverid`),
  ADD KEY `idx_messages_sender` (`senderid`);
ALTER TABLE `upfortrade` ADD KEY `idx_upfortrade_owner` (`owner`);
ALTER TABLE `items` ADD UNIQUE KEY `uq_items_uid` (`uid`);
ALTER TABLE `clans` ADD UNIQUE KEY `uq_clans_name` (`name`), ADD KEY `idx_clans_owner` (`owner`);
